const items = $input.all();
if (!items.length) {
  throw new Error('No certificate records returned by crt.sh');
}

let bestTs = -1;
for (const item of items) {
  const raw = item.json?.not_after;
  if (typeof raw !== 'string' || !raw) continue;
  const ts = Date.parse(raw.endsWith('Z') ? raw : `${raw}Z`);
  if (Number.isFinite(ts) && ts > bestTs) bestTs = ts;
}

if (bestTs < 0) {
  throw new Error('Could not parse any not_after timestamps from crt.sh response');
}

const daysLeft = Math.floor((bestTs - Date.now()) / 86400000);
return [{
  json: {
    host: 'n8n.joanmarcriera.es',
    source: 'crt.sh',
    recordCount: items.length,
    certExpiresAtUtc: new Date(bestTs).toISOString(),
    daysLeft,
    thresholdDays: 21,
    checkedAtUtc: new Date().toISOString()
  }
}];

if ($json.daysLeft < $json.thresholdDays) {
  throw new Error(`TLS certificate for ${$json.host} expires in ${$json.daysLeft} days (expiry ${$json.certExpiresAtUtc})`);
}
return {
  json: {
    ...$json,
    ok: true,
    message: `TLS certificate healthy: ${$json.daysLeft} days left`
  }
};
